import { Route } from '@angular/router';
import { MovieList } from './movie-list/movie-list';

export const appRoutes: Route[] = [
  { path: '', component: MovieList },
  // Placeholders for screens 2-5, implemented by later tickets.
  { path: 'screenings/:id/seats', children: [] },
  { path: 'screenings/:id/summary', children: [] },
  { path: 'screenings/:id/checkout', children: [] },
  { path: 'confirmation', children: [] },
  { path: '**', redirectTo: '' },
];
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}
/** Start of the given day in the browser's local time zone. */
export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/** Formats a date as `YYYY-MM-DD` using local calendar fields (not UTC). */
export function toIsoDate(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/** Parses a strict `YYYY-MM-DD` string; returns null when missing or not a real calendar date. */
export function parseIsoDate(value: string | null): Date | null {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day ? date : null;
}
import { HttpClient } from '@angular/common/http';
import { Component, DestroyRef, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { ActivatedRoute, Router } from '@angular/router';
import { forkJoin } from 'rxjs';
import { addDays, parseIsoDate, startOfDay, toIsoDate } from '../dates';
import { Movie, Screening } from '../models';

const API_URL = 'http://localhost:3000';
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

type LoadState = 'loading' | 'loaded' | 'error';

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatCardModule, MatDatepickerModule, MatFormFieldModule, MatInputModule, MatProgressSpinnerModule],
  templateUrl: './movie-list.html',
  styleUrl: './movie-list.scss',
})
export class MovieList {
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly destroyRef = inject(DestroyRef);

  protected readonly today = startOfDay(new Date());

  /** Today and the next four days, as shown in the day picker. */
  protected readonly days = [0, 1, 2, 3, 4].map((offset) => {
    const date = addDays(this.today, offset);
    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : WEEKDAYS[date.getDay()] };
  });

  private readonly queryParams = toSignal(this.route.queryParamMap, { requireSync: true });

  /** The `?date=` day if valid and not in the past, otherwise today. */
  protected readonly selectedDate = computed(() => {
    const requested = parseIsoDate(this.queryParams().get('date'));
    return requested && requested >= this.today ? requested : this.today;
  });
  protected readonly selectedIso = computed(() => toIsoDate(this.selectedDate()));

  /** The datepicker shows the date only when it is not one of the five day buttons. */
  protected readonly pickedDate = computed(() =>
    this.days.some((day) => day.iso === this.selectedIso()) ? null : this.selectedDate(),
  );

  protected readonly state = signal<LoadState>('loading');
  private readonly movies = signal<Movie[]>([]);
  private readonly screenings = signal<Screening[]>([]);

  protected readonly visibleMovies = computed(() => {
    const iso = this.selectedIso();
    const dayScreenings = this.screenings().filter((screening) => screening.date === iso);
    return this.movies()
      .map((movie) => ({
        movie,
        screenings: dayScreenings
          .filter((screening) => screening.movieId === movie.id)
          .sort((a, b) => a.time.localeCompare(b.time)),
      }))
      .filter((entry) => entry.screenings.length > 0);
  });

  constructor() {
    this.load();
  }

  protected load(): void {
    this.state.set('loading');
    forkJoin({
      movies: this.http.get<Movie[]>(`${API_URL}/movies`),
      screenings: this.http.get<Screening[]>(`${API_URL}/screenings`),
    })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: ({ movies, screenings }) => {
          this.movies.set(movies);
          this.screenings.set(screenings);
          this.state.set('loaded');
        },
        error: () => this.state.set('error'),
      });
  }

  protected selectDay(iso: string): void {
    void this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
  }

  protected selectDate(date: Date | null): void {
    if (!date || date < this.today) {
      return;
    }
    this.selectDay(toIsoDate(date));
  }

  protected openScreening(id: number): void {
    void this.router.navigate(['/screenings', id, 'seats']);
  }
}
<section class="movie-list-page">
  <div class="day-picker" data-testid="day-picker">
    @for (day of days; track day.iso) {
      @if (day.iso === selectedIso()) {
        <button
          mat-flat-button
          data-testid="day-button"
          [attr.data-date]="day.iso"
          data-selected="true"
          (click)="selectDay(day.iso)"
        >
          {{ day.label }}
        </button>
      } @else {
        <button
          mat-stroked-button
          data-testid="day-button"
          [attr.data-date]="day.iso"
          data-selected="false"
          (click)="selectDay(day.iso)"
        >
          {{ day.label }}
        </button>
      }
    }

    <mat-form-field class="date-field" subscriptSizing="dynamic">
      <mat-label>Other date</mat-label>
      <input
        matInput
        data-testid="date-picker"
        [matDatepicker]="picker"
        [min]="today"
        [value]="pickedDate()"
        (dateChange)="selectDate($event.value)"
      />
      <mat-datepicker-toggle matIconSuffix [for]="picker" />
      <mat-datepicker #picker />
    </mat-form-field>
  </div>

  @if (state() === 'loading') {
    <div class="state" data-testid="movies-loading">
      <mat-spinner diameter="32" />
      <span>Loading…</span>
    </div>
  } @else if (state() === 'error') {
    <div class="state">
      <p data-testid="movies-error">Failed to load movies</p>
      <button mat-flat-button data-testid="movies-retry-button" (click)="load()">Retry</button>
    </div>
  } @else {
    <div class="movie-list" data-testid="movie-list">
      @for (entry of visibleMovies(); track entry.movie.id) {
        <mat-card class="movie-card" data-testid="movie-card" [attr.data-movie-id]="entry.movie.id">
          <mat-card-content>
            <h2 class="movie-title" data-testid="movie-title">{{ entry.movie.title }}</h2>
            <div class="movie-meta">
              <span data-testid="movie-genre">{{ entry.movie.genre }}</span>
              <span data-testid="movie-runtime">{{ entry.movie.runtimeMinutes }} min</span>
              <span data-testid="movie-format">{{ entry.movie.format }}</span>
            </div>
            <div class="screenings">
              @for (screening of entry.screenings; track screening.id) {
                <button
                  mat-stroked-button
                  data-testid="screening-button"
                  [attr.data-screening-id]="screening.id"
                  (click)="openScreening(screening.id)"
                >
                  {{ screening.time }}
                </button>
              }
            </div>
          </mat-card-content>
        </mat-card>
      } @empty {
        <p class="state" data-testid="movies-empty">No screenings on this day</p>
      }
    </div>
  }
</section>
