      } @else {
        <button
          mat-stroked-button
          data-testid="day-button"
          [attr.data-date]="day.iso"
          data-selected="false"
          (click)="selectDay(day.iso)"
        >
          {{ day.label }}
        </button>
      }
    }

    <mat-form-field class="date-field" subscriptSizing="dynamic">
      <mat-label>Other date</mat-label>
      <input
        matInput
        data-testid="date-picker"
        [matDatepicker]="picker"
        [min]="today"
        [value]="pickedDate()"
        (dateChange)="selectDate($event.value)"
      />
      <mat-datepicker-toggle matIconSuffix [for]="picker" />
      <mat-datepicker #picker />
    </mat-form-field>
  </div>

  @if (state() === 'loading') {
    <div class="state" data-testid="movies-loading">
      <mat-spinner diameter="32" />
      <span>Loading…</span>
    </div>
  } @else if (state() === 'error') {
    <div class="state">
      <p data-testid="movies-error">Failed to load movies</p>
      <button mat-flat-button data-testid="movies-retry-button" (click)="load()">Retry</button>
    </div>
  } @else {
    <div class="movie-list" data-testid="movie-list">
      @for (entry of visibleMovies(); track entry.movie.id) {
        <mat-card class="movie-card" data-testid="movie-card" [attr.data-movie-id]="entry.movie.id">
          <mat-card-content>
            <h2 class="movie-title" data-testid="movie-title">{{ entry.movie.title }}</h2>
            <div class="movie-meta">
              <span data-testid="movie-genre">{{ entry.movie.genre }}</span>
              <span data-testid="movie-runtime">{{ entry.movie.runtimeMinutes }} min</span>
              <span data-testid="movie-format">{{ entry.movie.format }}</span>
            </div>
            <div class="screenings">
              @for (screening of entry.screenings; track screening.id) {
                <button
                  mat-stroked-button
                  data-testid="screening-button"
                  [attr.data-screening-id]="screening.id"
                  (click)="openScreening(screening.id)"
                >
                  {{ screening.time }}
                </button>
              }
            </div>
          </mat-card-content>
        </mat-card>
      } @empty {
        <p class="state" data-testid="movies-empty">No screenings on this day</p>
      }
    </div>
  }
</section>
