74	 * Couches in row 15 are built as one cell per pair of columns (1–2, 3–4, … 23–24).
75	 */
76	export function buildAuditorium(occupiedSeats: readonly string[]): AuditoriumRow[] {
77	  const occupied = new Set(occupiedSeats);
78	  const isOccupied = (row: number, column: number) => occupied.has(`R${row}C${column}`);
79	
80	  return Array.from({ length: ROW_COUNT }, (_, index) => {
81	    const row = index + 1;
82	    const cells: AuditoriumCell[] = [
83	      { kind: 'aisle', row, gridColumn: trackSpan(LEFT_AISLE_TRACK) },
84	      { kind: 'aisle', row, gridColumn: trackSpan(RIGHT_AISLE_TRACK) },
85	    ];
86	
87	    for (let column = 1; column <= COLUMN_COUNT; column++) {
88	      if (row <= ENTRANCE_LAST_ROW && column <= 4) {
89	        continue;
90	      }
91	
92	      if (row === COUCH_ROW) {
93	        if (column % 2 === 1) {
94	          cells.push({
95	            kind: 'couch',
96	            row,
97	            columnStart: column,
98	            columnEnd: column + 1,
99	            gridColumn: columnSpan(column, column + 1),
100	            state: isOccupied(row, column) || isOccupied(row, column + 1) ? 'unavailable' : 'available',
101	          });
102	        }
103	        continue;
104	      }
105	
106	      cells.push({
107	        kind: 'seat',
108	        row,
109	        column,
110	        gridColumn: columnSpan(column, column),
111	        state: seatState(row, column, isOccupied(row, column)),
112	      });
113	    }
114	
115	    return { row, cells };
116	  });
117	}
