2	export type SeatState = 'available' | 'accessible' | 'unavailable';
3	
4	export const ROW_COUNT = 15;
5	export const COLUMN_COUNT = 24;
6	
7	/** Rows 1 to 10 have no seats in columns 1 to 4: that space is the entrance. */
8	const ENTRANCE_LAST_ROW = 10;
9	const COUCH_ROW = 15;
10	const ACCESSIBLE_ROW = 1;
11	const ACCESSIBLE_FIRST_COLUMN = 10;
12	const ACCESSIBLE_LAST_COLUMN = 15;
13	
14	/**
15	 * The auditorium is a CSS grid with 28 tracks per row: track 1 is the left row label, tracks
16	 * 2–5 are columns 1–4, track 6 is the left aisle, tracks 7–22 are columns 5–20, track 23 is the
17	 * right aisle, tracks 24–27 are columns 21–24 and track 28 is the right row label.
18	 */
19	const LEFT_AISLE_TRACK = 6;
20	const RIGHT_AISLE_TRACK = 23;
21	
22	interface CellBase {
23	  row: number;
24	  /** CSS `grid-column` value, e.g. `2 / 3`. */
25	  gridColumn: string;
26	}
27	
28	export interface SeatCell extends CellBase {
29	  kind: 'seat';
30	  column: number;
31	  state: SeatState;
32	}
33	
34	export interface CouchCell extends CellBase {
35	  kind: 'couch';
36	  columnStart: number;
37	  columnEnd: number;
38	  state: 'available' | 'unavailable';
39	}
40	
41	export interface AisleCell extends CellBase {
42	  kind: 'aisle';
43	}
44	
45	export type AuditoriumCell = SeatCell | CouchCell | AisleCell;
46	
47	export interface AuditoriumRow {
48	  row: number;
49	  cells: AuditoriumCell[];
50	}
51	
52	/** Grid track holding the given seat column. */
53	function columnTrack(column: number): number {
54	  if (column <= 4) {
55	    return column + 1;
56	  }
57	  if (column <= 20) {
58	    return column + 2;
59	  }
60	  return column + 3;
61	}
62	
63	/** `grid-column` value covering the tracks of columns `first` to `last` (inclusive). */
64	function columnSpan(first: number, last: number): string {
65	  return `${columnTrack(first)} / ${columnTrack(last) + 1}`;
66	}
67	
68	function trackSpan(track: number): string {
69	  return `${track} / ${track + 1}`;
70	}
71	
72	/**
73	 * Builds the 15 rows of the auditorium from the occupied seat identifiers (`R<row>C<column>`).
74	 * Couches in row 15 are built as one cell per pair of columns (1–2, 3–4, … 23–24).
75	 */
76	export function buildAuditorium(occupiedSeats: readonly string[]): AuditoriumRow[] {
77	  const occupied = new Set(occupiedSeats);
78	  const isOccupied = (row: number, column: number) => occupied.has(`R${row}C${column}`);
79	
80	  return Array.from({ length: ROW_COUNT }, (_, index) => {
81	    const row = index + 1;
82	    const cells: AuditoriumCell[] = [
83	      { kind: 'aisle', row, gridColumn: trackSpan(LEFT_AISLE_TRACK) },
84	      { kind: 'aisle', row, gridColumn: trackSpan(RIGHT_AISLE_TRACK) },
85	    ];
86	
87	    for (let column = 1; column <= COLUMN_COUNT; column++) {
88	      if (row <= ENTRANCE_LAST_ROW && column <= 4) {
89	        continue;
90	      }
91	
92	      if (row === COUCH_ROW) {
93	        if (column % 2 === 1) {
94	          cells.push({
95	            kind: 'couch',
96	            row,
97	            columnStart: column,
98	            columnEnd: column + 1,
99	            gridColumn: columnSpan(column, column + 1),
100	            state: isOccupied(row, column) || isOccupied(row, column + 1) ? 'unavailable' : 'available',
101	          });
102	        }
103	        continue;
104	      }
105	
106	      cells.push({
107	        kind: 'seat',
108	        row,
109	        column,
110	        gridColumn: columnSpan(column, column),
111	        state: seatState(row, column, isOccupied(row, column)),
112	      });
113	    }
114	
115	    return { row, cells };
116	  });
117	}
118	
119	function seatState(row: number, column: number, occupied: boolean): SeatState {
120	  if (occupied) {
121	    return 'unavailable';
122	  }
123	  const accessible =
124	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
125	  return accessible ? 'accessible' : 'available';
126	}
