import { AuditoriumCell, SeatCell, CouchCell, buildAuditorium } from './auditorium';

const seatsOf = (cells: AuditoriumCell[]) => cells.filter((cell): cell is SeatCell => cell.kind === 'seat');
const couchesOf = (cells: AuditoriumCell[]) => cells.filter((cell): cell is CouchCell => cell.kind === 'couch');

describe('buildAuditorium', () => {
  it('has 15 rows numbered 1 to 15', () => {
    expect(buildAuditorium([]).map((row) => row.row)).toEqual(Array.from({ length: 15 }, (_, i) => i + 1));
  });

  it('has columns 5 to 24 in rows 1 to 10 and 1 to 24 in rows 11 to 14', () => {
    const rows = buildAuditorium([]);
    for (const { row, cells } of rows.slice(0, 10)) {
      const columns = seatsOf(cells).map((seat) => seat.column);
      expect(columns).toEqual(Array.from({ length: 20 }, (_, i) => i + 5));
      expect(row).toBeGreaterThan(0);
    }
    for (const { cells } of rows.slice(10, 14)) {
      expect(seatsOf(cells).map((seat) => seat.column)).toEqual(Array.from({ length: 24 }, (_, i) => i + 1));
    }
  });

  it('has 12 couches in row 15 covering 1-2 through 23-24', () => {
    const couches = couchesOf(buildAuditorium([])[14].cells);
    expect(couches.map((couch) => [couch.columnStart, couch.columnEnd])).toEqual(
      Array.from({ length: 12 }, (_, i) => [i * 2 + 1, i * 2 + 2]),
    );
    expect(seatsOf(buildAuditorium([])[14].cells)).toEqual([]);
  });

  it('has two aisles in every row', () => {
    for (const { cells } of buildAuditorium([])) {
      expect(cells.filter((cell) => cell.kind === 'aisle')).toHaveLength(2);
    }
  });

  it('has 308 selectable elements', () => {
    const cells = buildAuditorium([]).flatMap((row) => row.cells);
    expect(seatsOf(cells).length + couchesOf(cells).length).toBe(308);
    expect(couchesOf(cells).length).toBe(12);
  });

  it('keeps each column at the same grid position in every row', () => {
    const positions = new Map<number, Set<string>>();
    for (const { cells } of buildAuditorium([])) {
      for (const seat of seatsOf(cells)) {
        positions.set(seat.column, (positions.get(seat.column) ?? new Set()).add(seat.gridColumn));
      }
    }
    for (const [, placements] of positions) {
      expect(placements.size).toBe(1);
    }
  });

  it('marks accessible seats in row 1, columns 10 to 15', () => {
    const accessible = seatsOf(buildAuditorium([])[0].cells).filter((seat) => seat.state === 'accessible');
    expect(accessible.map((seat) => seat.column)).toEqual([10, 11, 12, 13, 14, 15]);
  });

  it('marks occupied seats and couches with either seat occupied as unavailable', () => {
    const rows = buildAuditorium(['R3C7', 'R15C6']);
    expect(seatsOf(rows[2].cells).find((seat) => seat.column === 7)?.state).toBe('unavailable');
    expect(seatsOf(rows[2].cells).find((seat) => seat.column === 8)?.state).toBe('available');
    const couches = couchesOf(rows[14].cells);
    expect(couches.find((couch) => couch.columnStart === 5)?.state).toBe('unavailable');
    expect(couches.find((couch) => couch.columnStart === 1)?.state).toBe('available');
  });

  it('never marks couches as accessible', () => {
    const couches = couchesOf(buildAuditorium([])[14].cells);
    expect(couches.every((couch) => couch.state === 'available')).toBe(true);
  });
});
==== seat-selection/auditorium.ts
/** Seat state as drawn on the map. Ticket 03 adds `selected`. */
export type SeatState = 'available' | 'accessible' | 'unavailable';

export const ROW_COUNT = 15;
export const COLUMN_COUNT = 24;

/** Rows 1 to 10 have no seats in columns 1 to 4: that space is the entrance. */
const ENTRANCE_LAST_ROW = 10;
const COUCH_ROW = 15;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;

/**
 * The auditorium is a CSS grid with 28 tracks per row: track 1 is the left row label, tracks
 * 2–5 are columns 1–4, track 6 is the left aisle, tracks 7–22 are columns 5–20, track 23 is the
 * right aisle, tracks 24–27 are columns 21–24 and track 28 is the right row label.
 */
const LEFT_AISLE_TRACK = 6;
const RIGHT_AISLE_TRACK = 23;

interface CellBase {
  row: number;
  /** CSS `grid-column` value, e.g. `2 / 3`. */
  gridColumn: string;
}

export interface SeatCell extends CellBase {
  kind: 'seat';
  column: number;
  state: SeatState;
}

export interface CouchCell extends CellBase {
  kind: 'couch';
  columnStart: number;
  columnEnd: number;
  state: 'available' | 'unavailable';
}

export interface AisleCell extends CellBase {
  kind: 'aisle';
}

export type AuditoriumCell = SeatCell | CouchCell | AisleCell;

export interface AuditoriumRow {
  row: number;
  cells: AuditoriumCell[];
}

/** Grid track holding the given seat column. */
function columnTrack(column: number): number {
  if (column <= 4) {
    return column + 1;
  }
  if (column <= 20) {
    return column + 2;
  }
  return column + 3;
}

/** `grid-column` value covering the tracks of columns `first` to `last` (inclusive). */
function columnSpan(first: number, last: number): string {
  return `${columnTrack(first)} / ${columnTrack(last) + 1}`;
}

function trackSpan(track: number): string {
  return `${track} / ${track + 1}`;
}

/**
 * Builds the 15 rows of the auditorium from the occupied seat identifiers (`R<row>C<column>`).
 * Couches in row 15 are built as one cell per pair of columns (1–2, 3–4, … 23–24).
 */
export function buildAuditorium(occupiedSeats: readonly string[]): AuditoriumRow[] {
  const occupied = new Set(occupiedSeats);
  const isOccupied = (row: number, column: number) => occupied.has(`R${row}C${column}`);

  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const row = index + 1;
    const cells: AuditoriumCell[] = [
      { kind: 'aisle', row, gridColumn: trackSpan(LEFT_AISLE_TRACK) },
      { kind: 'aisle', row, gridColumn: trackSpan(RIGHT_AISLE_TRACK) },
    ];

    for (let column = 1; column <= COLUMN_COUNT; column++) {
      if (row <= ENTRANCE_LAST_ROW && column <= 4) {
        continue;
      }

      if (row === COUCH_ROW) {
        if (column % 2 === 1) {
          cells.push({
            kind: 'couch',
            row,
            columnStart: column,
            columnEnd: column + 1,
            gridColumn: columnSpan(column, column + 1),
            state: isOccupied(row, column) || isOccupied(row, column + 1) ? 'unavailable' : 'available',
          });
        }
        continue;
      }

      cells.push({
        kind: 'seat',
        row,
        column,
        gridColumn: columnSpan(column, column),
        state: seatState(row, column, isOccupied(row, column)),
      });
    }

    return { row, cells };
  });
}

function seatState(row: number, column: number, occupied: boolean): SeatState {
  if (occupied) {
    return 'unavailable';
  }
  const accessible =
    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
  return accessible ? 'accessible' : 'available';
}
