63	/** `grid-column` value covering the tracks of columns `first` to `last` (inclusive). */
64	function columnSpan(first: number, last: number): string {
65	  return `${columnTrack(first)} / ${columnTrack(last) + 1}`;
66	}
67	
68	function trackSpan(track: number): string {
69	  return `${track} / ${track + 1}`;
70	}
