13	function parseBooking(raw: string | null): Booking | null {
14	  if (!raw) {
15	    return null;
16	  }
17	  try {
18	    const value = JSON.parse(raw) as Partial<Booking>;
19	    if (typeof value.screeningId !== 'number' || !Array.isArray(value.seats)) {
20	      return null;
21	    }
22	    const seats = value.seats;
23	    return seats.every((seat) => typeof seat === 'string') ? { screeningId: value.screeningId, seats } : null;
24	  } catch {
