30	@Injectable({ providedIn: 'root' })
31	export class BookingService {
32	  /** The stored booking, or null when there is none. */
33	  current(): Booking | null {
34	    return parseBooking(sessionStorage.getItem(STORAGE_KEY));
35	  }
36	
