    88	  private loadDetails(id: string): Observable<SummaryDetails> {
    89	    return this.http.get<Screening>(`${API_URL}/screenings/${id}`).pipe(
    90	      switchMap((screening) =>
    91	        this.http
    92	          .get<Movie>(`${API_URL}/movies/${screening.movieId}`)
    93	          .pipe(map((movie) => ({ screening, movie }))),
    94	      ),
    95	    );
