     1	/** Seat state as drawn on the map. */
     2	export type SeatState = 'available' | 'accessible' | 'selected' | 'unavailable';
     3	
     4	/** A couch is never accessible. */
     5	export type CouchState = Exclude<SeatState, 'accessible'>;
     6	
     7	export const ROW_COUNT = 15;
     8	export const COLUMN_COUNT = 24;
     9	
    10	/** Rows 1 to 10 have no seats in columns 1 to 4: that space is the entrance. */
    11	const ENTRANCE_LAST_ROW = 10;
    12	export const COUCH_ROW = 15;
    13	const ACCESSIBLE_ROW = 1;
    14	const ACCESSIBLE_FIRST_COLUMN = 10;
    15	const ACCESSIBLE_LAST_COLUMN = 15;
    16	
    17	/**
    18	 * The auditorium is a CSS grid with 28 tracks per row: track 1 is the left row label, tracks
    19	 * 2–5 are columns 1–4, track 6 is the left aisle, tracks 7–22 are columns 5–20, track 23 is the
    20	 * right aisle, tracks 24–27 are columns 21–24 and track 28 is the right row label.
    21	 */
    22	const LEFT_AISLE_TRACK = 6;
    23	const RIGHT_AISLE_TRACK = 23;
    24	
    25	interface CellBase {
    26	  row: number;
    27	  /** CSS `grid-column` value, e.g. `2 / 3`. */
    28	  gridColumn: string;
    29	}
    30	
    31	export interface SeatCell extends CellBase {
    32	  kind: 'seat';
    33	  column: number;
    34	  state: SeatState;
    35	}
    36	
    37	export interface CouchCell extends CellBase {
    38	  kind: 'couch';
    39	  columnStart: number;
    40	  columnEnd: number;
    41	  state: CouchState;
    42	}
    43	
    44	export interface AisleCell extends CellBase {
    45	  kind: 'aisle';
    46	}
    47	
    48	export type AuditoriumCell = SeatCell | CouchCell | AisleCell;
    49	
    50	export interface AuditoriumRow {
    51	  row: number;
    52	  cells: AuditoriumCell[];
    53	}
    54	
    55	/** Grid track holding the given seat column. */
    56	function columnTrack(column: number): number {
    57	  if (column <= 4) {
    58	    return column + 1;
    59	  }
    60	  if (column <= 20) {
    61	    return column + 2;
    62	  }
    63	  return column + 3;
    64	}
    65	
    66	/** `grid-column` value covering the tracks of columns `first` to `last` (inclusive). */
    67	function columnSpan(first: number, last: number): string {
    68	  return `${columnTrack(first)} / ${columnTrack(last) + 1}`;
    69	}
    70	
    71	function trackSpan(track: number): string {
    72	  return `${track} / ${track + 1}`;
    73	}
    74	
    75	/** Seat identifiers (`R<row>C<column>`) covered by a seat or couch; a couch covers two. */
    76	export function seatIdsOf(cell: SeatCell | CouchCell): string[] {
    77	  if (cell.kind === 'seat') {
    78	    return [seatId(cell.row, cell.column)];
    79	  }
    80	  return [seatId(cell.row, cell.columnStart), seatId(cell.row, cell.columnEnd)];
    81	}
    82	
    83	export function seatId(row: number, column: number): string {
    84	  return `R${row}C${column}`;
    85	}
    86	
    87	/**
    88	 * Builds the 15 rows of the auditorium from the occupied seat identifiers (`R<row>C<column>`)
    89	 * and the selected ones. Couches in row 15 are built as one cell per pair of columns (1–2,
    90	 * 3–4, … 23–24).
    91	 */
    92	export function buildAuditorium(
    93	  occupiedSeats: readonly string[],
    94	  selectedSeats: ReadonlySet<string> = new Set(),
    95	): AuditoriumRow[] {
    96	  const occupied = new Set(occupiedSeats);
    97	  const isOccupied = (row: number, column: number) => occupied.has(seatId(row, column));
    98	  const isSelected = (row: number, column: number) => selectedSeats.has(seatId(row, column));
    99	
   100	  return Array.from({ length: ROW_COUNT }, (_, index) => {
   101	    const row = index + 1;
   102	    const cells: AuditoriumCell[] = [
   103	      { kind: 'aisle', row, gridColumn: trackSpan(LEFT_AISLE_TRACK) },
   104	      { kind: 'aisle', row, gridColumn: trackSpan(RIGHT_AISLE_TRACK) },
   105	    ];
   106	
   107	    for (let column = 1; column <= COLUMN_COUNT; column++) {
   108	      if (row <= ENTRANCE_LAST_ROW && column <= 4) {
   109	        continue;
   110	      }
   111	
   112	      if (row === COUCH_ROW) {
   113	        if (column % 2 === 1) {
   114	          cells.push({
   115	            kind: 'couch',
   116	            row,
   117	            columnStart: column,
   118	            columnEnd: column + 1,
   119	            gridColumn: columnSpan(column, column + 1),
   120	            state: couchState(
   121	              isOccupied(row, column) || isOccupied(row, column + 1),
   122	              isSelected(row, column) || isSelected(row, column + 1),
   123	            ),
   124	          });
   125	        }
   126	        continue;
   127	      }
   128	
   129	      cells.push({
   130	        kind: 'seat',
   131	        row,
   132	        column,
   133	        gridColumn: columnSpan(column, column),
   134	        state: seatState(row, column, isOccupied(row, column), isSelected(row, column)),
   135	      });
   136	    }
   137	
   138	    return { row, cells };
   139	  });
   140	}
   141	
   142	function couchState(occupied: boolean, selected: boolean): CouchState {
   143	  if (occupied) {
   144	    return 'unavailable';
   145	  }
   146	  return selected ? 'selected' : 'available';
   147	}
   148	
   149	function seatState(row: number, column: number, occupied: boolean, selected: boolean): SeatState {
   150	  if (occupied) {
   151	    return 'unavailable';
   152	  }
   153	  if (selected) {
   154	    return 'selected';
   155	  }
   156	  const accessible =
   157	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
   158	  return accessible ? 'accessible' : 'available';
   159	}
