    23	export class Summary {
    24	  private readonly http = inject(HttpClient);
    25	  private readonly router = inject(Router);
    26	  private readonly route = inject(ActivatedRoute);
    27	  private readonly booking = inject(BookingService);
    28	
    29	  protected readonly details = signal<SummaryDetails | null>(null);
    30	  /** Seat identifiers of the booking; kept in step with sessionStorage on every removal. */
    31	  private readonly seatIds = signal<readonly string[]>([]);
    32	
    33	  protected readonly tickets = computed(() => ticketsOf(this.seatIds()));
    34	  protected readonly formatPrice = formatPrice;
    35	  protected readonly totalLabel = computed(() => `Total: ${formatPrice(totalOf(this.tickets()))}`);
    36	
    37	  constructor() {
    38	    this.route.paramMap
    39	      .pipe(
    40	        map((params) => params.get('id') ?? ''),
    41	        tap(() => this.details.set(null)),
    42	        switchMap((id) =>
    43	          this.loadDetails(id).pipe(
    44	            catchError(() => {
    45	              void this.router.navigateByUrl('/');
    46	              return EMPTY;
    47	            }),
    48	          ),
    49	        ),
    50	        takeUntilDestroyed(),
    51	      )
    52	      .subscribe((details) => {
    53	        this.details.set(details);
    54	        this.seatIds.set(this.booking.current()?.seats ?? []);
    55	      });
    56	  }
    57	
    58	  /** Takes a seat or couch out of the booking; removing the last one returns to the seat map. */
    59	  protected remove(ticket: Ticket): void {
    60	    const current = this.booking.current();
    61	    if (!current) {
    62	      return;
    63	    }
    64	    const seats = current.seats.filter((id) => !ticket.seatIds.includes(id));
    65	    this.booking.save({ ...current, seats });
    66	    this.seatIds.set(seats);
    67	    if (seats.length === 0) {
    68	      this.openScreen('seats');
    69	    }
    70	  }
    71	
    72	  protected back(): void {
    73	    this.openScreen('seats');
    74	  }
    75	
    76	  protected confirm(): void {
    77	    this.openScreen('checkout');
    78	  }
    79	
    80	  private openScreen(screen: 'seats' | 'checkout'): void {
    81	    const screeningId = this.booking.current()?.screeningId ?? this.details()?.screening.id;
    82	    if (screeningId !== undefined) {
    83	      void this.router.navigate(['/screenings', screeningId, screen]);
    84	    }
    85	  }
    86	
    87	  /** Loads the screening and its movie; both must load for the summary to show. */
    88	  private loadDetails(id: string): Observable<SummaryDetails> {
    89	    return this.http.get<Screening>(`${API_URL}/screenings/${id}`).pipe(
    90	      switchMap((screening) =>
    91	        this.http
    92	          .get<Movie>(`${API_URL}/movies/${screening.movieId}`)
    93	          .pipe(map((movie) => ({ screening, movie }))),
    94	      ),
    95	    );
    96	  }
    97	}
