    93	  /** Selects or deselects a seat or couch; a couch is always toggled as one unit. */
    94	  protected toggle(cell: SeatCell | CouchCell): void {
    95	    if (cell.state === 'unavailable') {
    96	      return;
    97	    }
    98	
    99	    const ids = seatIdsOf(cell);
   100	    const selected = new Set(this.selectedSeats());
   101	
   102	    if (cell.state === 'selected') {
   103	      ids.forEach((id) => selected.delete(id));
   104	    } else if (selected.size + ids.length > MAX_SEATS_PER_BOOKING) {
   105	      this.toast.show(MAX_SEATS_MESSAGE);
   106	      return;
   107	    } else {
   108	      ids.forEach((id) => selected.add(id));
   109	    }
   110	    this.selectedSeats.set(selected);
   111	    this.saveSelection(selected);
   112	  }
