    13	
    14	/** A booking holds at most this many seats; a couch counts as 2. */
    15	export const MAX_SEATS_PER_BOOKING = 10;
    16	const MAX_SEATS_MESSAGE = `Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`;
    17	
    18	const LEGEND = [
    19	  { state: 'available', label: 'Available' },
    20	  { state: 'selected', label: 'Selected' },
    21	  { state: 'unavailable', label: 'Unavailable' },
    22	  { state: 'accessible', label: 'Accessible' },
    23	] as const;
    24	
    25	@Component({
    26	  selector: 'app-seat-selection',
    27	  imports: [MatButtonModule],
    28	  templateUrl: './seat-selection.html',
    29	  styleUrl: './seat-selection.scss',
    30	})
    31	export class SeatSelection {
    32	  private readonly http = inject(HttpClient);
    33	  private readonly router = inject(Router);
    34	  private readonly route = inject(ActivatedRoute);
    35	  private readonly toast = inject(ToastService);
    36	  private readonly booking = inject(BookingService);
    37	
    38	  protected readonly screening = signal<Screening | null>(null);
    39	  /** Seat identifiers (`R<row>C<column>`) of the current selection. */
    40	  private readonly selectedSeats = signal<ReadonlySet<string>>(new Set());
    41	
    42	  protected readonly legend = LEGEND;
    43	  protected readonly selectedCount = computed(() => this.selectedSeats().size);
    44	
    45	  protected readonly showDate = computed(() => {
    46	    const screening = this.screening();
    47	    return screening ? formatShowDate(screening.date, screening.time) : '';
    48	  });
    49	
    50	  protected readonly rows = computed(() =>
    51	    buildAuditorium(this.screening()?.occupiedSeats ?? [], this.selectedSeats()),
    52	  );
    53	
    54	  /** One line per row with a selection, in ascending row and column order. */
    55	  protected readonly selectedRows = computed(() =>
    56	    this.rows()
    57	      .map(({ row, cells }) => ({
    58	        row,
    59	        seats: cells.flatMap((cell) => {
    60	          if (cell.kind === 'seat' && cell.state === 'selected') {
    61	            return [String(cell.column)];
    62	          }
    63	          if (cell.kind === 'couch' && cell.state === 'selected') {
    64	            return [`${cell.columnStart}-${cell.columnEnd}`];
    65	          }
    66	          return [];
    67	        }),
    68	      }))
    69	      .filter((line) => line.seats.length > 0),
    70	  );
    71	
    72	  constructor() {
    73	    this.route.paramMap
    74	      .pipe(
    75	        map((params) => params.get('id') ?? ''),
    76	        tap(() => this.screening.set(null)),
    77	        switchMap((id) =>
    78	          this.loadScreening(id).pipe(
    79	            catchError(() => {
    80	              void this.router.navigateByUrl('/');
    81	              return EMPTY;
    82	            }),
    83	          ),
    84	        ),
    85	        takeUntilDestroyed(),
    86	      )
    87	      .subscribe((screening) => {
    88	        this.screening.set(screening);
    89	        this.selectedSeats.set(this.openBooking(screening.id));
    90	      });
    91	  }
    92	
    93	  /** Selects or deselects a seat or couch; a couch is always toggled as one unit. */
    94	  protected toggle(cell: SeatCell | CouchCell): void {
    95	    if (cell.state === 'unavailable') {
    96	      return;
    97	    }
    98	
    99	    const ids = seatIdsOf(cell);
   100	    const selected = new Set(this.selectedSeats());
   101	
   102	    if (cell.state === 'selected') {
   103	      ids.forEach((id) => selected.delete(id));
   104	    } else if (selected.size + ids.length > MAX_SEATS_PER_BOOKING) {
   105	      this.toast.show(MAX_SEATS_MESSAGE);
   106	      return;
   107	    } else {
   108	      ids.forEach((id) => selected.add(id));
   109	    }
   110	    this.selectedSeats.set(selected);
   111	    this.saveSelection(selected);
   112	  }
   113	
   114	  protected cancel(): void {
   115	    this.booking.clear();
   116	    this.selectedSeats.set(new Set());
   117	    void this.router.navigateByUrl('/');
   118	  }
   119	
   120	  protected continueToSummary(): void {
   121	    const id = this.screening()?.id;
   122	    if (id === undefined || this.selectedCount() === 0) {
   123	      return;
   124	    }
   125	    void this.router.navigate(['/screenings', id, 'summary']);
   126	  }
   127	
   128	  /**
   129	   * Returns the seats of the booking in progress when it belongs to this screening. Otherwise
   130	   * starts a new, empty booking for the screening, replacing the previous one.
   131	   */
   132	  private openBooking(screeningId: number): ReadonlySet<string> {
   133	    const current = this.booking.current();
   134	    if (current?.screeningId === screeningId && current.paidEmail === undefined) {
   135	      return new Set(current.seats);
   136	    }
   137	    this.booking.save({ screeningId, seats: [] });
   138	    return new Set();
   139	  }
   140	
   141	  /** Stores the new selection; the checkout values of the booking are kept. */
   142	  private saveSelection(selected: ReadonlySet<string>): void {
   143	    const current = this.booking.current();
   144	    if (current) {
   145	      this.booking.save({ ...current, seats: [...selected] });
   146	    }
   147	  }
   148	
   149	  /** Loads the screening and its movie; the page only needs the screening, but both must load. */
   150	  private loadScreening(id: string): Observable<Screening> {
   151	    return this.http.get<Screening>(`${API_URL}/screenings/${id}`).pipe(
   152	      switchMap((screening) =>
   153	        this.http.get<Movie>(`${API_URL}/movies/${screening.movieId}`).pipe(map(() => screening)),
   154	      ),
   155	    );
   156	  }
   157	}
