    38	    this.route.paramMap
    39	      .pipe(
    40	        map((params) => params.get('id') ?? ''),
    41	        tap(() => this.details.set(null)),
    42	        switchMap((id) =>
    43	          this.loadDetails(id).pipe(
    44	            catchError(() => {
    45	              void this.router.navigateByUrl('/');
    46	              return EMPTY;
    47	            }),
    48	          ),
    49	        ),
    50	        takeUntilDestroyed(),
    51	      )
    52	      .subscribe((details) => {
    53	        this.details.set(details);
    54	        this.seatIds.set(this.booking.current()?.seats ?? []);
    55	      });
    56	  }
