    32	export class Checkout {
    33	  private readonly http = inject(HttpClient);
    34	  private readonly router = inject(Router);
    35	  private readonly toast = inject(ToastService);
    36	  private readonly booking = inject(BookingService);
    37	
    38	  /** The guard only opens this screen for an unpaid booking, so it is present here. */
    39	  private readonly stored = this.booking.current();
    40	  private readonly tickets = ticketsOf(this.stored?.seats ?? []);
    41	  protected readonly total = totalOf(this.tickets);
    42	
    43	  protected readonly form = createCheckoutForm(this.stored?.checkout);
    44	  protected readonly submitting = signal(false);
    45	  protected readonly payLabel = computed(() =>
    46	    this.submitting() ? 'Processing…' : `Pay ${formatPrice(this.total)}`,
    47	  );
    48	
    49	  constructor() {
    50	    // Every change is kept in the booking, so the values survive going back and reloading.
    51	    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.saveValues());
    52	  }
    53	
    54	  /** The message of a field, or null when it is valid or has not been left yet. */
    55	  protected error(field: CheckoutField): string | null {
    56	    return checkoutErrorMessage(this.form, field);
    57	  }
    58	
    59	  protected back(): void {
    60	    const screeningId = this.booking.current()?.screeningId;
    61	    if (screeningId !== undefined) {
    62	      void this.router.navigate(['/screenings', screeningId, 'summary']);
    63	    }
    64	  }
    65	
    66	  protected pay(): void {
    67	    if (this.submitting()) {
    68	      return;
    69	    }
    70	    this.form.markAllAsTouched();
    71	    if (this.form.invalid) {
    72	      this.toast.show(FORM_ERRORS_MESSAGE);
    73	      return;
    74	    }
    75	
    76	    const booking = this.booking.current();
    77	    if (!booking) {
    78	      void this.router.navigateByUrl('/');
    79	      return;
    80	    }
    81	
    82	    const values = this.form.getRawValue();
    83	    const reservation: NewReservation = {
    84	      screeningId: booking.screeningId,
    85	      seats: this.tickets.flatMap((ticket) => ticket.seatIds),
    86	      customer: {
    87	        firstName: values.firstName,
    88	        lastName: values.lastName,
    89	        email: values.email,
    90	        phone: values.phone,
    91	      },
    92	      totalPrice: this.total,
    93	    };
    94	
    95	    this.submitting.set(true);
    96	    this.http.post<Reservation>(`${API_URL}/reservations`, reservation).subscribe({
    97	      next: () => {
    98	        this.booking.save({ ...booking, checkout: values, paidEmail: values.email });
    99	        void this.router.navigateByUrl('/confirmation');
   100	      },
   101	      error: () => {
   102	        this.submitting.set(false);
   103	        this.toast.show(PAYMENT_FAILED_MESSAGE);
   104	      },
   105	    });
   106	  }
   107	
   108	  private saveValues(): void {
   109	    const current = this.booking.current();
   110	    if (current) {
   111	      this.booking.save({ ...current, checkout: this.form.getRawValue() });
   112	    }
   113	  }
   114	}
